import { guardProcessEnv } from "./helpers/env-guard.js";
guardProcessEnv();

import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { describe, it } from "vitest";
import {
	generateToolResultErrorBridgeExtension,
	resetToolResultErrorBridgeExtensionCache,
	writeToolResultErrorBridgeExtension,
} from "../../src/server/agent/tool-result-error-bridge-extension.js";

async function loadGeneratedExtension(): Promise<(pi: any) => void> {
	const source = generateToolResultErrorBridgeExtension();
	const mod = await import(`data:text/javascript,${encodeURIComponent(source)}`);
	return mod.default;
}

function makePi() {
	const handlers = new Map<string, Function>();
	const pi: any = {
		tool(spec: any, handler?: Function) {
			const name = typeof spec === "string" ? spec : spec.name;
			const fn = handler ?? spec.handler ?? spec.execute;
			handlers.set(name, fn);
		},
	};
	pi.tools = { register: (...args: any[]) => pi.tool(...args) };
	return { pi, handlers };
}

describe("tool result error bridge extension", () => {
	it("throws returned isError:true results so pi marks the tool result errored", async () => {
		const activate = await loadGeneratedExtension();
		const { pi, handlers } = makePi();
		activate(pi);
		pi.tool({ name: "x" }, async () => ({ content: [{ type: "text", text: "validation failed" }], isError: true }));

		await assert.rejects(
			() => handlers.get("x")!({}),
			(err: any) => err?.isError === true && /validation failed/.test(err.message),
		);
	});

	it("throws returned is_error:true results", async () => {
		const activate = await loadGeneratedExtension();
		const { pi, handlers } = makePi();
		activate(pi);
		pi.tools.register({ name: "x" }, async () => ({ content: [{ type: "text", text: "snake failed" }], is_error: true }));

		await assert.rejects(
			() => handlers.get("x")!({}),
			(err: any) => err?.is_error === true && /snake failed/.test(err.message),
		);
	});

	it("preserves successful returned results", async () => {
		const activate = await loadGeneratedExtension();
		const { pi, handlers } = makePi();
		activate(pi);
		pi.tool({ name: "x" }, async () => ({ content: [{ type: "text", text: "ok" }] }));

		assert.deepEqual(await handlers.get("x")!({}), { content: [{ type: "text", text: "ok" }] });
	});

	it("reprojects and bounds the actual resolved read_session return", async () => {
		const activate = await loadGeneratedExtension();
		const { pi, handlers } = makePi();
		activate(pi);
		const largeText = "\\\"\n😀".repeat(30_000);
		const envelope = {
			total: 1,
			returned: 1,
			offsetStart: 4,
			offsetEnd: 4,
			messages: [{
				index: 4,
				role: "toolResult",
				thinkingSignature: "provider-only",
				toolResults: [{
					ref: "r1",
					name: "read",
					toolName: "duplicate",
					status: "ok",
					isError: true,
					size: { type: "string", chars: largeText.length, lines: 30_001, bytes: Buffer.byteLength(largeText) },
					omitted: false,
					handle: "rs1:m4:b0:AAAAAAAAAAAAAAAAAAAAAAAAAAA",
					excerpt: { start: 0, end: largeText.length, text: largeText, nextCursor: null, complete: true },
				}],
			}],
		};
		pi.tool({ name: "read_session" }, async () => ({
			content: [{ type: "text", text: JSON.stringify(envelope) }, { type: "text", text: largeText }],
			details: { session_id: "target", envelope, messages: envelope.messages, extra: largeText },
		}));

		const result = await handlers.get("read_session")!({
			session_id: "target",
			include_tool_results: true,
			limit: 1,
		});
		assert.ok(Buffer.byteLength(JSON.stringify(result), "utf8") <= 50 * 1024);
		assert.equal(Object.hasOwn(result.details, "messages"), false);
		const projected = JSON.parse(result.content[0].text);
		assert.equal(projected.messages[0].thinkingSignature, undefined);
		assert.deepEqual(Object.keys(projected.messages[0].toolResults[0]).sort(),
			["excerpt", "handle", "name", "omitted", "ref", "size", "status"].sort());
		assert.equal(projected.messages[0].toolResults[0].name, "read");
	});

	it("uses a sub-1KiB structured fallback for unknown successful wrappers", async () => {
		const activate = await loadGeneratedExtension();
		const { pi, handlers } = makePi();
		activate(pi);
		const large = "never-echo-this".repeat(100_000);
		pi.tool({ name: "read_session" }, async () => ({ unknown: large }));

		const result = await handlers.get("read_session")!({
			session_id: "target",
			pattern: large,
			offset: 2,
			limit: 10,
		});
		assert.ok(Buffer.byteLength(JSON.stringify(result), "utf8") < 1024);
		assert.equal(JSON.stringify(result).includes("never-echo-this"), false);
		const projected = JSON.parse(result.content[0].text);
		assert.equal(projected.truncatedBy, "extension_return_unrecognized");
		assert.deepEqual(projected.continuationRequest, {
			kind: "retry",
			retrySameRequest: true,
			session_id: "target",
			sessionIdTruncated: false,
			offset: 2,
			limit: 10,
			patternOmitted: true,
		});
		assert.equal(projected.wrapperDiagnostics.actualBytes > 1_000_000, true);
	});

	it("repairs tampered cached bridge source before reuse", () => {
		const previousBobbitDir = process.env.BOBBIT_DIR;
		const root = fs.mkdtempSync(path.join(os.tmpdir(), "bobbit-tool-result-bridge-"));
		try {
			process.env.BOBBIT_DIR = root;
			resetToolResultErrorBridgeExtensionCache();

			const firstPath = writeToolResultErrorBridgeExtension();
			assert.ok(firstPath, "expected bridge extension path");
			fs.writeFileSync(firstPath!, "throw new Error('tampered');\n", "utf-8");

			const secondPath = writeToolResultErrorBridgeExtension();
			assert.equal(secondPath, firstPath);
			assert.equal(fs.readFileSync(secondPath!, "utf-8"), generateToolResultErrorBridgeExtension());
		} finally {
			resetToolResultErrorBridgeExtensionCache();
			if (previousBobbitDir === undefined) delete process.env.BOBBIT_DIR;
			else process.env.BOBBIT_DIR = previousBobbitDir;
			fs.rmSync(root, { recursive: true, force: true });
		}
	});
});
